#!/usr/bin/env bash
#
# Generated by Claude Code
#
# List unexpired coverage-html-* artifacts from recent workflow runs.
# Usage: coverage-artifacts.sh [repo] [num_runs]
# Exits non-zero on any API error or unexpected response shape.
set -euo pipefail

repo="${1:-GaloisInc/saw-script}"
num_runs="${2:-50}"

die() { echo "list-coverage-artifacts.sh: Error: $*" 1>&2; exit 1; }

# gh exits non-zero on HTTP errors and unparseable JSON; error() in the jq
# filter makes it exit non-zero when the JSON doesn't have the expected shape.
runs=$(gh api "repos/$repo/actions/runs" --method GET -F per_page="$num_runs" \
  --jq 'if (.workflow_runs | type) != "array"
        then error("unexpected response: no .workflow_runs array")
        else .workflow_runs[].id end') \
  || die "failed to list workflow runs for $repo"

if [ -z "$runs" ]; then
    die "no workflow runs returned for $repo"
fi

out=""
for run in $runs; do
  res=$(gh api "repos/$repo/actions/runs/$run/artifacts" --method GET -F per_page=100 \
    --jq 'if (.artifacts | type) != "array"
          then error("unexpected response: no .artifacts array")
          else .artifacts[]
            | select(.expired == false and (.name | startswith("coverage-html-")))
            | "\(.id) \(.name)" end') \
    || die "failed to list artifacts for run $run"
  if [ -n "$res" ]; then
      out+="$res"$'\n'
  fi
done

if [ -n "$out" ]; then
  printf '%s' "$out" | sort -u
fi
